  1	package com.loja.repository;
  2	
  3	import com.loja.model.*;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import java.sql.*;
  6	import java.time.Instant;
  7	import java.util.*;
  8	
  9	public class OrderRepository {
 10	    private final Database db;
 11	    private final ObjectMapper mapper = new ObjectMapper();
 12	
 13	    public OrderRepository(Database db) {
 14	        this.db = db;
 15	    }
 16	
 17	    public Order findById(String id) {
 18	        String sql = "SELECT id, cpf, email, status, created_at, paid_at, tracking_code, summary_json, items_json " +
 19	                     "FROM orders WHERE id = ?";
 20	        try (Connection conn = db.getConnection();
 21	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 22	            stmt.setString(1, id);
 23	            try (ResultSet rs = stmt.executeQuery()) {
 24	                if (rs.next()) {
 25	                    return mapOrder(rs);
 26	                }
 27	            }
 28	        } catch (SQLException e) {
 29	            throw new RuntimeException("Error finding order", e);
 30	        }
 31	        return null;
 32	    }
 33	
 34	    public void create(Order order) {
 35	        String sql = "INSERT INTO orders (id, cpf, email, status, created_at, paid_at, tracking_code, summary_json, items_json) " +
 36	                     "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)";
 37	        try (Connection conn = db.getConnection();
 38	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 39	            stmt.setString(1, order.id);
 40	            stmt.setString(2, order.cpf);
 41	            stmt.setString(3, order.email);
 42	            stmt.setString(4, order.status.name());
 43	            stmt.setObject(5, order.createdAt);
 44	            stmt.setObject(6, order.paidAt);
 45	            stmt.setString(7, order.trackingCode);
 46	            stmt.setString(8, mapper.writeValueAsString(order.summary));
 47	            stmt.setString(9, mapper.writeValueAsString(order.items));
 48	            stmt.executeUpdate();
 49	        } catch (Exception e) {
 50	            throw new RuntimeException("Error creating order", e);
 51	        }
 52	    }
 53	
 54	    public void updateStatus(String id, OrderStatus status) {
 55	        String sql = "UPDATE orders SET status = ? WHERE id = ?";
 56	        try (Connection conn = db.getConnection();
 57	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 58	            stmt.setString(1, status.name());
 59	            stmt.setString(2, id);
 60	            stmt.executeUpdate();
 61	        } catch (SQLException e) {
 62	            throw new RuntimeException("Error updating order status", e);
 63	        }
 64	    }
 65	
 66	    public void updateStatusAndPaidAt(String id, OrderStatus status, Instant paidAt) {
 67	        String sql = "UPDATE orders SET status = ?, paid_at = ? WHERE id = ?";
 68	        try (Connection conn = db.getConnection();
 69	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 70	            stmt.setString(1, status.name());
 71	            stmt.setObject(2, paidAt);
 72	            stmt.setString(3, id);
 73	            stmt.executeUpdate();
 74	        } catch (SQLException e) {
 75	            throw new RuntimeException("Error updating order", e);
 76	        }
